\begin{exercice}
Pour tout $x\in\R$, on pose $f(x)=x^2-2x-3$.

\begin{enumerate}
	\item \begin{enumerate}
		\item Montrer que $f(x)=(x-1)^2-4$. On appelle cette forme la \emph{forme canonique} de $f$.
		\item En déduire la valeur minimum de $f$ sur $\R$.
	\end{enumerate}

	\item \begin{enumerate}
		\item Montrer que $f(x)=(x+1)(x-3)$. On appelle cette forme la \emph{forme factorisée} de $f$.
		\item En déduire les solutions de l'équation $f(x)=0$.
		\item Résoudre $f(x)>0$.
	\end{enumerate}
\end{enumerate}
\end{exercice}

\begin{exercice}
\begin{enumerate}
	\item Factoriser les expressions suivantes :
	$$
	64-x^2\quad;\quad 36t^2-16\quad;\quad(x-3)^2-25 \quad;\quad (2x+7)^2-81.
	$$

	\item Pour tout $x\in\R$, on pose $g(x)=x^2+4x-12$.
	\begin{enumerate}
		\item Montrer que la forme canonique de $g$ est $g(x)=(x+2)^2-16$.
		\item En déduire une factorisation de $g(x)$.
		\item Résoudre $g(x)=0$.
		\item Résoudre $g(x)\leq 0$.
	\end{enumerate}
\end{enumerate}

\end{exercice}

\begin{exercice}
Pour tout $x\in\R$, on pose $f(x)=4x+7$.
\begin{enumerate}
	\item Exprimer en fonction de $h$ (on simplifiera au maximum) :

	\begin{tasks}(3)
		\task $f(2h)$ \task $f(2h+h)$ \task $f(-h)$
		\task $f(h^2)$ \task $f(4h)-f(3h)$ \task $f(-5+h)$
	\end{tasks}

	\item Simplifier au maximum $f(3+h)-f(3)$ puis $\dfrac{f(3+h)-f(3)}{h}$.
	\item On pose $g(x)=-2x+3$.

	Simplifier 	$\dfrac{g(4+h)-g(4)}{h}$.


\end{enumerate}
\end{exercice}

\begin{exercice}
Pour tout $x\in\R$, on définit $p(x)=x^2+2x+3$.
\begin{enumerate}
	\item Montrer que $p(1+h)=h^2+4h+6$.
	\item Calculer puis factoriser $p(1+h)-p(1)$.
	\item Simplifier au maximum $\dfrac{p(1+h)-p(1)}{h}$.
\end{enumerate}
\end{exercice}

\begin{exercice}
Pour tout réel $x\geq 1$ on pose $f(x)=\dfrac{1}{x}$. Simplifier au maximum $\dfrac{f(2+h)-f(2)}{h}$.



\emph{Indication : diviser par $h$, c'est multiplier par $\dfrac{1}{h}$ \ldots}
\end{exercice}

\begin{exercice}
\textbf{Recopier} et compléter les équivalences suivantes. Il faudra utiliser les bons signes ($<$, $\leq$, etc.) Aucune justification n'est demandée.


\begin{enumerate}
    \item $|x-2|\leq 10\Longleftrightarrow \ldots x  \ldots$
    \item $|x-\sqrt{3}|<3 \Longleftrightarrow \ldots  x  \ldots$
    \item $|x+1|\leq 2 \Longleftrightarrow \ldots x  \ldots$
\end{enumerate}
\end{exercice}

