\begin{exercice}
\begin{enumerate}
	\item Pour que $A$ soit le symétrique de $E$ par rapport à $C$ il faut et il suffit que $C$ soit le milieu de $[AE]$. 

Le milieu de $[AE]$ a pour coordonnées  $\left(\frac{-2+1}{2}\,;\,\frac{5+2}{2}\right)=\left(\frac{-1}{2}\,;\,\frac{7}{2}\right)$ qui ne sont pas celles de $C$. $A$ n'est pas le symétrique de $E$ par rapport à $C$.
	\item $A$ doit être le milieu de $[CD]$. Notons $D(x,y)$. Le milieu de $[DC]$ a pour coordonnées $\left(\frac{4+x}{2};\frac{y-1}{2}\right)$. Par identification avec les coordonnées de $A$, on obtient le système suivant :

	$$
	\left\lbrace\begin{array}{l}
		-2=\frac{4+x}{2} \\
		5=\frac{y-1}{2}
	\end{array}\right.
	\Longleftrightarrow
	\left\lbrace\begin{array}{l}
		x=-8 \\
		y=11
	\end{array}\right.
	\Longleftrightarrow D(-8;11).
	$$
\end{enumerate}

\end{exercice}

\begin{exercice}
\begin{enumerate}
	\item Dans le triangle $EFG$ rectangle en $F$, $\tan(27^\circ)=\frac{8}{EF}$. On isole $EF$ avec une règle de trois : $EF=\frac{8}{\tan(27^\circ)}$. Ce qui donne, arrondi au mm, $EF\approx 15@7$dm.
	\item L'aire $\mathcal{A}$ cherchée vaut $EF\*FG\div 2\approx 15@7\*8\div 2$. Soit $\mathcal{A}\approx 62@8$dm$^2$.
\end{enumerate}
\end{exercice}

\begin{exercice}
D'après le cours $\sin^2(\widehat{a})+\cos^2(\widehat{a})=1$. De cette égalité on tire $\sin(\widehat{a})=\pm\sqrt{1-\left(\frac{33}{65}\right)^2}=\pm\frac{56}{65}$. Mais le sinus d'un angle aigu est toujours positif et alors $\sin(\widehat{a})=\frac{56}{65}$.
\end{exercice}

