y=-\frac{1}{2}x-4.
$$
On nomme $\mathscr{P}$ la courbe associée à la fonction $f$.

\begin{enumerate}
	\item Calculer $f'(x)$.
	\item Déterminer la tangente $\mathscr{T}_1$ à $\mathscr{P}$ qui est parallèle à $(d)$.
	\item {\it --- Hors barème ---}
	\begin{enumerate}
		\item \textit{Propriété : Deux droites sont perpendiculaire si, et seulement si, le produit de leurs pentes vaut $-1$.}

		Grâce à cette propriété, donner l'équation de la tangente $\mathscr{T}_2$ à $\mathscr{P}$ qui est perpendiculaire à $\mathscr{T}_1$.
		\item Déterminer la position relative de $\mathscr{T}_2$ et $\mathscr{P}$.
	\end{enumerate}
\end{enumerate}
\end{exercice}

