\begin{exercice}
Soit $k(x)=\dfrac{x+3}{x-1}$.
      \begin{enumerate}
      		\item Peut-on calculer $k(1)$ ? On justifiera la réponse donnée.
         \item Montrer que le taux variation $t(h)$ de $k$ en $a=2$ vaut~:
         $$
         t(h)=-\frac{4}{h+1}.
         $$
         \item Calculer alors $k'(2)$.
         \item Donner une équation de la tangente à la courbe de $k$ au point d'abscisse $2$.
      \end{enumerate}
\end{exercice}

