\begin{enumerate}
	\item Déterminer la forme canonique de $f$.
	\item Donner la forme développée et réduite de $f$.
	\item Marquer en vert sur le graphique précédent l'emplacement des racines de $f$. Découper puis coller le graphique sur la copie.
	\item Retrouver par le calcul la valeur exacte des racines de $f$.
\end{enumerate}
\end{exercice}

\begin{exercice}
\begin{enumerate}
	  \item Que peut-on dire du discriminant d'un trinôme du second degré n'ayant qu'une seule racine ? Que se passe-t-il graphiquement dans ce cas ?
	  \item Inventer un trinôme du second degré n'ayant qu'une seule racine.
	  \item Inventer un trinôme du second degré ayant $2$ racines et dont la parabole a pour sommet $S(2;5)$.
      \end{enumerate}
\end{exercice}

\begin{exercice}
Soit $g(x)=2x^2+12x-3$.

Dresser le tableau de variations de $g$.
\end{exercice}

\begin{exercice}
Pour chaque polynôme, donner son tableau de signes puis résoudre l'inéquation proposée.

\begin{enumerate}
	\item $f(x)=x^2-3x-4$ ; $f(x)>0$.
	\item $g(x)=-4x^2+4x+35$ ; $g(x)\geq 0$.
	\item $h(x)=(3-x)(7-x)$ ; $h(x)<0$.
\end{enumerate}
\end{exercice}

\begin{exercice}
\begin{enumerate}
	\item Donner l'équation de deux paraboles distinctes $\C_1$ et $\C_2$ passant chacune par les points $A(-1~;~0)$ et $B(5~;~0)$. $\C_1$ et $\C_2$ n'auront pas les branches orientées dans le même sens.
	\item Donner l'équation de la parabole passant par le point $P(4~;~-4)$ et ayant pour sommet le point $S(1~;2)$.
\end{enumerate}
\end{exercice}

\begin{exercice}
Les fonctions $f$, $g$ et $h$ sont définies sur $\R$ par~:

$f(x)=-(x-2)^2-1\quad ; \quad g(x)=\dfrac{1}{2}x^2+2$

\hfill $h(x)=\dfrac{3}{20}(x-2)^2$.\hfill \hfill


