		\item En déduire une équation cartésienne de $(GHK)$.
	\end{enumerate}
	\item \begin{enumerate}
		\item Montrer  qu'une représentation paramétrique de la droite $(d)$ passant par $L$ et orthogonale au plan $(GHK)$ est :

		$$
		(d):\left\lbrace
		\begin{array}{l}
			x=\dfrac{1}{2},\\
			y=-2t,\quad\mbox{$t\in\R$},\\
			z=\dfrac{1}{2}+t.
		\end{array}\right.
		$$
		\item En déduire les coordonnées du projeté orthogonal $I$ du point $L$ sur le plan $(GHK)$.
	\end{enumerate}
	\item Calculer le volume de la pyramide de base $GHK$ et de sommet principal $L$.

	\emph{On rappelle aimablement la formule du volume d'une pyramide : $\mathscr{V}=\dfrac{\mbox{base}\*\mbox{hauteur}}{3}$}	


\end{enumerate}
\end{exercice}

